export const ESSENTIAL_IDS = Object.keys(ESSENTIAL_SHAPES);
export const isEssentialShape = (id) => Object.prototype.hasOwnProperty.call(ESSENTIAL_SHAPES, id);
const fract = (n) => n - Math.floor(n);
function sample(geometry, count) {
    let distance = 0;
    const segments = geometry.flatMap((p) => p.vertices.slice(1).flatMap((b, i) => {
        const a = p.vertices[i], length = Math.hypot(b[0] - a[0], b[1] - a[1]);
        if (length < 1e-6)
            return [];
        distance += length * p.width;
        return [{ a, b, length, width: p.width, end: distance }];
    }));
    let index = 0;
    return Array.from({ length: count }, (_, i) => {
        const at = ((i + 0.5) / count) * distance;
        while (segments[index].end < at)
            index++;
        const s = segments[index], t = (at - s.end + s.length * s.width) / (s.length * s.width), offset = (fract(i * 0.61803398875 + 0.3) - 0.5) * s.width;
        return {
            x: (s.a[0] +
                (s.b[0] - s.a[0]) * t -
                ((s.b[1] - s.a[1]) / s.length) * offset -
                12) /
                12,
            y: (s.a[1] +
                (s.b[1] - s.a[1]) * t +
                ((s.b[0] - s.a[0]) / s.length) * offset -
                12) /
                12,
            z: 0.25,
        };
    });
}
const cache = new Map();
export function getEssentialPoints(id, count) {
    const key = id + ":" + count;
    const cached = cache.get(key);
    if (cached)
        return cached;
    const result = sample(ESSENTIAL_SHAPES[id].geometry, count);
    if (cache.size >= 96)
        cache.delete(cache.keys().next().value);
    cache.set(key, result);
    return result;
}
